/* Presentation only. Educational data, task IDs and persistence are untouched. */
(()=>{
 const root=document.documentElement;
 const art=document.querySelector('.hero-art');
 const pts=Array.from({length:101},(_,i)=>{const x=-2.5+i*.05;return `${80+(x+2.5)*80},${254-x*x*30}`}).join(' ');
 if(art){art.removeAttribute('aria-hidden');art.innerHTML=`<figure class="science-plate"><div class="plate-top"><span>МАТКЛУБ / ИССЛЕДОВАНИЕ 01</span><span>ƒ</span></div><svg viewBox="0 0 560 340" role="img" aria-labelledby="sciencePlotTitle"><title id="sciencePlotTitle">График функции y = x² и касательная y = 2x − 1 в точке (1; 1)</title><defs><pattern id="scienceGrid" width="40" height="30" patternUnits="userSpaceOnUse" x="40" y="14"><path d="M40 0H0V30" fill="none" stroke="currentColor" stroke-opacity=".09"/></pattern></defs><rect x="40" y="14" width="480" height="300" fill="url(#scienceGrid)"/><g class="science-axes" fill="none"><path d="M40 254H520M280 314V14"/><path d="m513 250 7 4-7 4m-237-233 4-7 4 7"/></g><g class="science-labels"><text x="514" y="277">x</text><text x="260" y="25">y</text><text x="262" y="272">0</text><text x="356" y="275">1</text><text x="260" y="229">1</text><text x="430" y="44" class="science-equation">y = x²</text></g><polyline points="${pts}" fill="none" class="science-parabola"/><path d="M200 344L520 104" class="science-tangent"/><path d="M360 254V224H280" class="science-projection"/><circle cx="360" cy="224" r="5" class="science-point"/><g class="science-labels"><text x="372" y="214">A (1; 1)</text><text x="394" y="148">y = 2x − 1</text><text x="80" y="309">f′(1) = 2</text></g></svg><figcaption><span>01 / ФУНКЦИЯ И ЕЁ ИЗМЕНЕНИЕ</span><span>Точная точка. Новая связь.</span></figcaption></figure>`;}
 if(art){const wave=Array.from({length:161},(_,i)=>{const t=i/40;return `${60+t*115},${165-80*Math.sin(Math.PI*t)}`}).join(' ');art.insertAdjacentHTML('beforeend',`<figure class="science-plate physics-plate"><div class="plate-top"><span>МАТКЛУБ / ИССЛЕДОВАНИЕ 02</span><span>λ</span></div><svg viewBox="0 0 560 340" role="img" aria-label="Гармоническое колебание: x = A sin(ωt), амплитуда A и период T"><defs><pattern id="waveGrid" width="28.75" height="40" patternUnits="userSpaceOnUse"><path d="M28.75 0H0V40" fill="none" stroke="currentColor" stroke-opacity=".09"/></pattern></defs><rect x="60" y="45" width="460" height="240" fill="url(#waveGrid)"/><path d="M60 165H528M60 285V45" class="science-axes" fill="none"/><polyline points="${wave}" class="science-parabola" fill="none"/><path d="M117.5 85H60M117.5 165V85M60 265H290" class="science-projection"/><circle cx="117.5" cy="85" r="5" class="science-point"/><g class="science-labels"><text x="38" y="90">A</text><text x="40" y="170">0</text><text x="520" y="188">t</text><text x="40" y="40">x</text><text x="167" y="284">T</text><text x="330" y="50" class="science-equation">x = A sin(ωt)</text><text x="60" y="315">ω = 2π / T</text></g></svg><figcaption><span>02 / КОЛЕБАНИЯ И ЗАКОНОМЕРНОСТИ</span><span>Амплитуда. Период. Движение.</span></figcaption></figure>`);}
 const sync=()=>{
  const physics=root.dataset.domain==='physics';
  const h=document.querySelector('.hero h1');if(h)h.innerHTML=physics?'Увидеть явление.<br><em>Понять закон.</em>':'Математика.<br>Физика.<br><em>Суть вещей.</em>';
  const kicker=document.querySelector('.hero-copy>.eyebrow');if(kicker)kicker.textContent='НЕЗАВИСИМАЯ ОБРАЗОВАТЕЛЬНАЯ СРЕДА';
  const p=document.querySelector('.hero-copy>p');if(p)p.textContent=physics?'От наблюдения к модели. Изучай теорию, исследуй явления в лаборатории и решай задачи с подробными разборами.':'От школьной темы к самостоятельному мышлению. Теория, задачи с подробными разборами и инструменты для исследования.';
  const foot=document.querySelector('.hero-foot');if(foot)foot.textContent=physics?'ФИЗИКА / 7–11 КЛАССЫ / ОГЭ':'МАТЕМАТИКА / 6–11 КЛАССЫ / ОГЭ И ЕГЭ';
  const heading=document.querySelector('#sectionTitle');if(heading&&root.dataset.page==='catalog')heading.textContent='Учебная программа';
 };
 if(typeof render==='function'){const previous=render;render=function(...args){const result=previous.apply(this,args);sync();return result;};}
 sync();
 const small=document.querySelector('.hero-actions #start');if(small)small.innerHTML='Выбрать тему <span aria-hidden="true">↗</span>';
 const gear=document.querySelector('.header-settings');if(gear)gear.innerHTML='<svg viewBox="0 0 24 24" width="20" height="20" fill="none" stroke="currentColor" stroke-width="1.5" aria-hidden="true"><path d="M4 6h16M4 12h16M4 18h16"/><circle cx="9" cy="6" r="2"/><circle cx="15" cy="12" r="2"/><circle cx="9" cy="18" r="2"/></svg>';
})();
